import hashlib,json,os,pathlib,subprocess,sys,time
root=pathlib.Path('/workspace/tcl-lsp-partial');base=pathlib.Path('/workspace/tmp/proof-lsp-scope/tiny-boundary-v2');target=base/'target';assert not target.exists();assert (root/'Cargo.toml').is_file() and (root/'Cargo.lock').is_file();env=os.environ.copy();env.update({'PATH':'/workspace/.cargo/bin:'+env.get('PATH',''),'CARGO_HOME':'/workspace/.cargo','RUSTUP_HOME':'/workspace/.rustup','CARGO_TARGET_DIR':str(target),'CARGO_INCREMENTAL':'0','CARGO_PROFILE_DEV_DEBUG':'0','CARGO_PROFILE_TEST_DEBUG':'0','CARGO_BUILD_JOBS':'1'})
