def seal(packages):
 files={root/'Cargo.toml',root/'Cargo.lock',root/'rust-toolchain.toml'};files.update((root/'rust').glob('*/Cargo.toml'));files.update((root/'rust').glob('*/*/Cargo.toml'))
 for name in packages:files.update(p for p in (root/'rust'/name).rglob('*') if p.is_file())
 for p in [root/'.cargo/config',root/'.cargo/config.toml',root/'rust/.cargo/config',root/'rust/.cargo/config.toml',pathlib.Path('/workspace/.cargo/config'),pathlib.Path('/workspace/.cargo/config.toml')]:files.add(p)
 return {str(p):digest(p) if p.is_file() else None for p in sorted(files)}
results=[]
for label,package,selector,packages in [('leaf','tcl-core-types','naming::tests::consumes_complete_separator_runs',['tcl-core-types']),('lexer','tcl-lexer','ranges::shared_boundary_tests::array_index_nested_variables_use_the_shared_ascii_name_scanner',['tcl-core-types','tcl-dialect','tcl-lexer'])]:
 before=seal(packages);(base/(label+'-before.json')).write_text(json.dumps(before,indent=2,sort_keys=True)+'\n');assert str(root/'Cargo.toml') in before and str(root/'Cargo.lock') in before
 args=['cargo','test','--offline','-p',package,'--lib',selector,'--','--exact'];start=time.monotonic();stop=None;peak=0
 with (base/(label+'.stdout')).open('wb') as out,(base/(label+'.stderr')).open('wb') as err:
  proc=subprocess.Popen(args,cwd=root/'rust',env=env,stdout=out,stderr=err,start_new_session=True)
  while proc.poll() is None:
   du=subprocess.run(['du','-sk',str(target)],capture_output=True,text=True);size=int(du.stdout.split()[0]) if du.returncode==0 else 0;peak=max(peak,size)
   if time.monotonic()-start>30 or size>150*1024:
    stop='time budget' if time.monotonic()-start>30 else 'target size budget';os.killpg(proc.pid,15);proc.wait(timeout=5);break
   time.sleep(.2)
  code=proc.wait()
 elapsed=time.monotonic()-start;du=subprocess.run(['du','-sk',str(target)],capture_output=True,text=True);size=int(du.stdout.split()[0]) if du.returncode==0 else 0;peak=max(peak,size);out=(base/(label+'.stdout')).read_bytes();err=(base/(label+'.stderr')).read_bytes();after=seal(packages);passed=code==0 and b'test result: ok. 1 passed; 0 failed; 0 ignored;' in out
 row={'label':label,'command':args,'scope':'Named Rust unit test only; selected package dependency source directories and membership, workspace root manifest/lock, workspace crate manifests, toolchain file and applicable cargo config paths sealed. External toolchains/dependency cache, other crate sources, git HEAD, status docs and native providers excluded.','files':len(before),'source_inventory_unchanged':before==after,'inventory_sha256':hashlib.sha256(json.dumps(before,sort_keys=True).encode()).hexdigest(),'exit_code':code,'stopped_for':stop,'elapsed_seconds':round(elapsed,3),'target_kib':size,'peak_sampled_kib':peak,'exactly_one_passed':passed,'stdout_sha256':hashlib.sha256(out).hexdigest(),'stderr_sha256':hashlib.sha256(err).hexdigest()};results.append(row);print(json.dumps(row),flush=True)
 if not (passed and before==after and stop is None and peak<=150*1024):break
 bins=[p for p in (target/'debug/deps').glob(package.replace('-','_')+'-*') if p.is_file() and p.stat().st_mode&0o111];assert len(bins)==1,bins;binary=bins[0];binary_before=digest(binary);run=subprocess.run([str(binary),'--exact',selector],capture_output=True,timeout=5);(base/(label+'-rerun.stdout')).write_bytes(run.stdout);(base/(label+'-rerun.stderr')).write_bytes(run.stderr);row['rerun']={'exit_code':run.returncode,'exactly_one_passed':run.returncode==0 and b'test result: ok. 1 passed; 0 failed; 0 ignored;' in run.stdout,'binary':str(binary),'binary_sha256_before':binary_before,'binary_sha256_after':digest(binary),'source_inventory_unchanged':before==seal(packages),'stdout_sha256':hashlib.sha256(run.stdout).hexdigest(),'stderr_sha256':hashlib.sha256(run.stderr).hexdigest()}
 if not (row['rerun']['exactly_one_passed'] and row['rerun']['source_inventory_unchanged'] and row['rerun']['binary_sha256_before']==row['rerun']['binary_sha256_after']):break
(base/'receipt.json').write_text(json.dumps({'scope':'Two scoped software tests only; no native provider, other proof or global gate result. Prior v1 receipts are flawed and retained separately.','results':results},indent=2)+'\n');sys.exit(0 if len(results)==2 and all(r.get('rerun',{}).get('exactly_one_passed') for r in results) else 1)
